import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        long a = nextLong(), b = nextLong(), cost = 0;
        // Subtraction-based Euclid, merging runs of the same subtraction.
        while (a != b) {
            if (a < b) {
                long t = a;
                a = b;
                b = t;
            }
            long q = a / b, r = a % b;
            if (r == 0) {
                cost += q - 1;  // stop as soon as a reaches b
                a = b;
            } else {
                cost += q;
                a = r;
            }
        }
        System.out.println(cost);
    }
}

